package com.nivor.habit.dto;import com.nivor.habit.*;import java.time.*;public record HabitResponse(Long id,String name,String description,HabitFrequency frequency,int targetCount,LocalTime reminderTime,String color,boolean active,LocalDateTime createdAt,LocalDateTime updatedAt){public static HabitResponse from(Habit h){return new HabitResponse(h.getId(),h.getName(),h.getDescription(),h.getFrequency(),h.getTargetCount(),h.getReminderTime(),h.getColor(),h.isActive(),h.getCreatedAt(),h.getUpdatedAt());}}
